"""Argument parsing for the command line interface."""
import os
import re
import sys
from .ui import UI

FIELDS = 'project description head pending version created languages dependencies authors last-change contributors url commits churn lines-of-code size license'.split()
# long name: (short name, metavar, kind, possible values, maximum arity)
SPECS = {
 'help': ('h',None,'flag',None,0), 'version':('V',None,'flag',None,0),
 'disabled-fields':('d','FIELD','list',FIELDS,None), 'no-title':(None,None,'flag',None,0),
 'number-of-authors':(None,'NUM','int',None,1), 'number-of-languages':(None,'NUM','int',None,1),
 'number-of-file-churns':(None,'NUM','int',None,1), 'churn-pool-size':(None,'NUM','int',None,1),
 'exclude':('e','EXCLUDE','list',None,None), 'no-bots':(None,'REGEX','regex',None,0),
 'no-merges':(None,None,'flag',None,0), 'email':('E',None,'flag',None,0),
 'http-url':(None,None,'flag',None,0), 'hide-token':(None,None,'flag',None,0),
 'include-hidden':(None,None,'flag',None,0),
 'type':('T','TYPE','list',['programming','markup','prose','data'],None),
 'text-colors':('t','X','colors',None,6), 'iso-time':('z',None,'flag',None,0),
 'number-separator':(None,'SEPARATOR','value',['plain','comma','space','underscore'],1),
 'no-bold':(None,None,'flag',None,0), 'ascii-input':(None,'STRING','value',None,1),
 'ascii-colors':('c','X','colors',None,None), 'ascii-language':('a','LANGUAGE','value',UI['keys'],1),
 'true-color':(None,'WHEN','value',['auto','never','always'],1),
 'image':('i','IMAGE','value',None,1), 'image-protocol':(None,'PROTOCOL','value',['kitty','sixel','iterm'],1),
 'color-resolution':(None,'VALUE','value',['16','32','64','128','256'],1),
 'no-color-palette':(None,None,'flag',None,0), 'no-art':(None,None,'flag',None,0),
 'nerd-fonts':(None,None,'flag',None,0), 'output':('o','FORMAT','value',['json','yaml'],1),
 'generate':(None,'SHELL','value',['bash','elvish','fish','powershell','zsh'],1),
 'languages':('l',None,'flag',None,0), 'package-managers':('p',None,'flag',None,0),
}
SHORT = {v[0]:k for k,v in SPECS.items() if v[0]}

class Exit(Exception):
    def __init__(self, code, text='', stderr=True):
        self.code, self.text, self.stderr = code, text, stderr


def label(name):
    _, meta, kind, _, _ = SPECS[name]
    if kind == 'regex': return '--no-bots[=<REGEX>]'
    s = '--'+name
    if meta: s += ' <'+meta+'>'
    if kind in ('list','colors'): s += '...'
    return s


def jaro_winkler(a,b):
    if a==b:return 1.0
    if not a or not b:return 0.0
    dist=max(len(a),len(b))//2-1
    dist=max(dist,0)
    x=[False]*len(a); y=[False]*len(b)
    for i,c in enumerate(a):
        for j in range(max(0,i-dist),min(len(b),i+dist+1)):
            if not y[j] and c==b[j]:x[i]=y[j]=True;break
    m=sum(x)
    if not m:return 0.0
    sa=[c for i,c in enumerate(a) if x[i]];sb=[c for i,c in enumerate(b) if y[i]]
    t=sum(c!=d for c,d in zip(sa,sb))/2
    score=(m/len(a)+m/len(b)+(m-t)/m)/3
    if score>0.7:
        prefix=0
        for c,d in zip(a[:4],b[:4]):
            if c!=d:break
            prefix+=1
        score+=prefix*.1*(1-score)
    return score

class Parser:
    def __init__(self,argv,program):
        self.argv=argv; self.program=program
        self.opts={'number-of-authors':3,'number-of-languages':6,'number-of-file-churns':3,
                   'number-separator':'plain','true-color':'auto','color-resolution':'64',
                   'disabled-fields':[],'exclude':[],'type':['programming','markup'],
                   'text-colors':[],'ascii-colors':[]}
        self.seen=[];self.path=None
    def usage(self, generic=False):
        if generic:return f'Usage: {self.program} [OPTIONS] [INPUT]'
        items=[]
        # Diagnostics generally include options that have already been parsed.
        for k in self.seen:
            if k not in ('help','version') and k not in items:items.append(k)
        text=' '.join(label(k) for k in items)
        return f'Usage: {self.program} '+(text+' ' if text else '[OPTIONS] ')+('[INPUT]' if self.path is None else '<INPUT>')
    def fail(self,msg,usage=False,tip=''):
        text='error: '+msg+'\n'
        if tip:text+='\n  tip: '+tip+'\n'
        if usage:text+='\n'+self.usage()+'\n'
        text+="\nFor more information, try '--help'.\n"
        raise Exit(2,text)
    def unexpected(self,arg):
        tip=''
        if arg.startswith('-'):
            similars=[]
            if arg.startswith('--'):
                similars=sorted(((jaro_winkler(arg[2:],k),k) for k in SPECS),reverse=True)
            if similars and similars[0][0]>.8:
                tip=f"a similar argument exists: '--{similars[0][1]}'"
            else:tip=f"to pass '{arg}' as a value, use '-- {arg}'"
        self.fail(f"unexpected argument '{arg}' found",True,tip)
    def missing(self,key):
        possible=SPECS[key][3]
        msg=f"a value is required for '{label(key)}' but none was supplied"
        if possible:msg+='\n  [possible values: '+', '.join(possible)+']'
        self.fail(msg)
    def invalid(self,key,v,reason=None):
        msg=f"invalid value '{v}' for '{label(key)}'"
        if reason:msg+=': '+reason
        values=SPECS[key][3];tip=''
        if values:
            msg+='\n  [possible values: '+', '.join(values)+']'
            best=sorted(((jaro_winkler(v,c),c) for c in values),reverse=True)
            if best and best[0][0]>.8:tip=f"a similar value exists: '{best[0][1]}'"
        self.fail(msg,False,tip)
    def convert(self,key,v):
        kind=SPECS[key][2]
        values=SPECS[key][3]
        if values and v not in values:self.invalid(key,v)
        if kind in ('int','colors'):
            if not v or not re.fullmatch(r'\+?[0-9]+',v):
                self.invalid(key,v,'cannot parse integer from empty string' if not v else 'invalid digit found in string')
            n=int(v)
            if n>18446744073709551615:self.invalid(key,v,'number too large to fit in target type')
            if kind=='colors' and n>=16:self.invalid(key,v,f'{n} is not in 0..16')
            return n
        if kind=='regex':
            try:re.compile(v)
            except re.error as e:
                idx=getattr(e,'pos',0) or 0
                reason='unclosed character class' if 'unterminated character' in str(e) else ('unclosed group' if 'unterminated subpattern' in str(e) else 'repetition operator missing expression' if 'nothing to repeat' in str(e) else 'unopened group' if 'unbalanced parenthesis' in str(e) else str(e).split(' at position')[0])
                self.invalid(key,v,'regex parse error:\n    '+v+'\n    '+' '*idx+'^\nerror: '+reason)
        return v
    def parse(self):
        args=self.argv; i=0;end=False
        while i<len(args):
            arg=args[i];i+=1
            if end or not arg.startswith('-') or arg=='-':
                if self.path is not None:self.unexpected(arg)
                self.path=arg;continue
            if arg=='--':end=True;continue
            attached=None
            if arg.startswith('--'):
                text=arg[2:];key,sep,attached=text.partition('=')
                if not sep:attached=None
                if key not in SPECS:self.unexpected(arg)
            else:
                short=arg[1:2]
                if short not in SHORT:self.unexpected('-'+short)
                key=SHORT[short]
                if len(arg)>2:
                    if SPECS[key][2]=='flag':
                        args=args[:i]+['-'+arg[2:]]+args[i:]
                    else:attached=arg[2:].removeprefix('=')
            _,_,kind,_,maximum=SPECS[key]
            if key=='help':
                if attached is not None:self.fail(f"unexpected value '{attached}' for '--help' found; no more were expected",True)
                text=UI['help_long' if arg=='--help' else 'help_short'].replace('Usage: executable','Usage: '+self.program)
                raise Exit(0,text,False)
            if key=='version':raise Exit(0,'onefetch 2.25.0\n',False)
            if key in self.seen and kind not in ('list','colors'):
                # Repeated-option diagnostics use a generic usage.
                raise Exit(2,f"error: the argument '{label(key)}' cannot be used multiple times\n\nUsage: {self.program} [OPTIONS] [INPUT]\n\nFor more information, try '--help'.\n")
            if kind=='flag':
                self.seen.append(key)
                if attached is not None:self.fail(f"unexpected value '{attached}' for '--{key}' found; no more were expected",True)
                self.opts[key]=True;continue
            if kind=='regex':
                self.opts[key]=self.convert(key,attached if attached is not None else r'\[bot\]')
                self.seen.append(key);continue
            vals=[]
            if attached is not None:vals=[attached]
            else:
                limit=maximum or len(args)
                while i<len(args) and len(vals)<limit:
                    nxt=args[i]
                    if nxt.startswith('-') and nxt!='-':break
                    vals.append(nxt);i+=1
                    if kind not in ('list','colors'):break
                if not vals:
                    if i<len(args) and re.match(r'^-\d',args[i]):self.unexpected(args[i])
                    self.missing(key)
            converted=[self.convert(key,x) for x in vals]
            if kind in ('list','colors'):
                if key not in self.seen:self.opts[key]=[]
                self.opts[key].extend(converted)
            else:self.opts[key]=converted[0]
            self.seen.append(key)
        if 'image-protocol' in self.opts and 'image' not in self.opts:
            other=' '.join(label(k) for k in self.seen if k not in ('image-protocol',))
            usage=f'Usage: {self.program} --image <IMAGE> --image-protocol <PROTOCOL>'
            if other:usage+=' '+other
            if self.path is not None:usage+=' <INPUT>'
            raise Exit(2,"error: the following required arguments were not provided:\n  --image <IMAGE>\n\n"+usage+"\n\nFor more information, try '--help'.\n")
        self.opts['input']=self.path if self.path is not None else '.'
        return self.opts


def parse(argv):
    return Parser(list(argv),os.path.basename(sys.argv[0]) or 'executable').parse()
PY"}

