def collect_languages(repo,opts):
    root=repo.root
    # Ask Git only about ignore rules; source files themselves are read from the work tree.
    files=[]
    for directory,dirs,names in os.walk(root,followlinks=False):
        dirs[:]=[d for d in dirs if d!='.git' and (opts.get('include-hidden') or not d.startswith('.'))]
        for name in names:
            if name=='.git' or (name.startswith('.') and not opts.get('include-hidden')):continue
            path=os.path.join(directory,name)
            if os.path.islink(path) or not os.path.isfile(path):continue
            rel=os.path.relpath(path,root).replace(os.sep,'/')
            if not excluded(rel,opts['exclude']):files.append(rel)
    ignored=set()
    if files:
        result=repo.git('check-ignore','--no-index','-z','--stdin',input=('\0'.join(files)+'\0').encode(),binary=True,check=False)
        ignored=set(result.decode('utf-8','replace').split('\0'))
    extra=[]
    for directory,dirs,names in os.walk(root,followlinks=False):
        dirs[:]=[d for d in dirs if d!='.git' and (opts.get('include-hidden') or not d.startswith('.'))]
        for f in ('.ignore','.tokeignore'):
            if f in names:
                try:
                    rules=open(os.path.join(directory,f),encoding='utf8').read().splitlines()
                    prefix=os.path.relpath(directory,root)
                    extra.append(('' if prefix=='.' else prefix+'/',[x.strip() for x in rules if x.strip() and not x.startswith('#')]))
                except OSError:pass
    counts=Counter()
    for rel in files:
        if rel in ignored:continue
        if any(rel.startswith(prefix) and excluded(rel[len(prefix):],rules) for prefix,rules in extra):continue
        try:
            raw=open(os.path.join(root,rel),'rb').read()
            if b'\0' in raw:continue
            text=raw.decode('utf-8-sig')
        except (OSError,UnicodeError):continue
        lang=identify(rel,text)
        if lang not in LANGUAGES or LANGUAGES[lang]['type'] not in opts['type']:continue
        count=count_lines(text,lang)
        if count:counts[lang]+=count
    ordered=sorted(counts.items(),key=lambda x:(-x[1],LANGUAGES[x[0]]['order']))
    total=sum(counts.values())
    return [{'language':lang,'percentage':count/total*100.0} for lang,count in ordered],total
