"""Repository metadata, history, manifest and license inspection."""
import ast
import datetime
import json
import math
import os
import re
import subprocess
import time
import urllib.parse
from collections import Counter
from .cli import Exit, FIELDS
from .languages import collect_languages, excluded


def human_date(timestamp,iso=False):
    if iso:
        try:return datetime.datetime.fromtimestamp(timestamp,datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
        except (ValueError,OverflowError,OSError):return '1970-01-01T00:00:00Z'
    delta=int(time.time())-timestamp
    s=abs(delta)
    if s<=10:return 'now'
    if s<=45:text=f'{s} seconds'
    elif s<=90:text='a minute'
    elif s<=2700:text=f'{max(2,s//60)} minutes'
    elif s<=5400:text='an hour'
    elif s<=79200:text=f'{max(2,s//3600)} hours'
    elif s<=129600:text='a day'
    elif s<=561600:text=f'{max(2,s//86400)} days'
    elif s<=907200:text='a week'
    elif s<=2505600:text=f'{max(2,s//604800)} weeks'
    elif s<=3888000:text='a month'
    elif s<=29808000:text=f'{max(2,s//2592000)} months'
    elif s<=47088000:text='a year'
    else:text=f'{max(2,s//31536000)} years'
    return text+' ago' if delta>=0 else 'in '+text


def human_size(n):
    units=['B','KiB','MiB','GiB','TiB','PiB','EiB']
    idx=0; value=float(n)
    while value>=1024 and idx<len(units)-1:value/=1024;idx+=1
    if not idx:return str(n)+' B'
    return f'{value:.2f}'.rstrip('0').rstrip('.')+' '+units[idx]


def parse_toml(text):
    """Small TOML reader for package metadata, tables, arrays, and inline tables."""
    result={};table=result
    pending='';quote=None
    def split(text,sep=','):
        out=[];start=0;depth=0;q=None;i=0
        while i<len(text):
            c=text[i]
            if q:
                if c=='\\' and q=='"':i+=2;continue
                if c==q:q=None
            elif c in "\"'":q=c
            elif c in '[{':depth+=1
            elif c in ']}':depth-=1
            elif c==sep and depth==0:out.append(text[start:i]);start=i+1
            i+=1
        out.append(text[start:]);return out
    def value(t):
        t=t.strip()
        if t.startswith(('"""',"'''")) and t.endswith(t[:3]):return t[3:-3].removeprefix('\n')
        if t.startswith('"'):
            try:return json.loads(t)
            except ValueError:raise ValueError('invalid string')
        if t.startswith("'") and t.endswith("'"):return t[1:-1]
        if t.startswith('{') and t.endswith('}'):
            obj={}
            for piece in split(t[1:-1]):
                if not piece.strip():continue
                k,eq,v=piece.partition('=')
                if not eq:raise ValueError('bad table')
                obj[k.strip().strip('"\'')]=value(v)
            return obj
        if t.startswith('[') and t.endswith(']'):return [value(x) for x in split(t[1:-1]) if x.strip()]
        if t in ('true','false'):return t=='true'
        try:return int(t.replace('_',''))
        except ValueError:
            try:return float(t)
            except ValueError:raise ValueError('bad value')
    lines=text.splitlines();i=0
    while i<len(lines):
        line=lines[i];i+=1
        # Strip comments without stripping hash characters within strings.
        q=None;clean='';j=0
        while j<len(line):
            c=line[j]
            if q:
                clean+=c
                if c=='\\' and q=='"' and j+1<len(line):j+=1;clean+=line[j]
                elif c==q:q=None
            else:
                if c=='#':break
                if c in '\"\'':q=c
                clean+=c
            j+=1
        line=clean.strip()
        if not line:continue
        if line.startswith('[') and line.endswith(']'):
            array=line.startswith('[[')
            parts=line[2:-2] if array else line[1:-1]
            table=result
            for part in split(parts,'.'):
                part=part.strip().strip('"\'')
                if array and part==parts.split('.')[-1]:
                    table=table.setdefault(part,[]);table.append({});table=table[-1]
                else:table=table.setdefault(part,{})
            continue
        k,eq,v=line.partition('=')
        if not eq:raise ValueError('invalid assignment')
        v=v.strip()
        if v.startswith(('"""',"'''")):
            delimiter=v[:3]
            if v.count(delimiter)<2:
                while i<len(lines):
                    v+='\n'+lines[i];i+=1
                    if delimiter in lines[i-1]:break
        else:
            # Multiline dependency arrays are common in manifests.
            while (v.count('[')>v.count(']') or v.count('{')>v.count('}')) and i<len(lines):
                v+='\n'+lines[i].split('#',1)[0];i+=1
        target=table;parts=split(k.strip(),'.')
        for part in parts[:-1]:target=target.setdefault(part.strip().strip('"\''),{})
        target[parts[-1].strip().strip('"\'')]=value(v)
    return result


def package_info(root):
    """The first readable, valid root manifest supplies package metadata."""
    try:entries=list(os.scandir(root))
    except OSError:return None
    for entry in entries:
        if entry.name not in ('Cargo.toml','package.json'):continue
        try:
            text=open(entry.path,encoding='utf-8').read()
            if entry.name=='package.json':
                obj=json.loads(text);package=obj;manager='Npm'
                if not isinstance(obj,dict):continue
                if not isinstance(obj.get('name'),str) or not isinstance(obj.get('version'),str):continue
                desc=obj.get('description');license=obj.get('license','');deps=obj.get('dependencies',{})
            else:
                obj=parse_toml(text);package=obj.get('package');manager='Cargo'
                if not isinstance(package,dict):continue
                if not isinstance(package.get('name'),str) or not isinstance(package.get('version'),str):continue
                desc=package.get('description');license=package.get('license','');deps=obj.get('dependencies',{})
            if desc is not None and not isinstance(desc,str):continue
            if not isinstance(license,str):continue
            if not isinstance(deps,dict):continue
            # Npm dependency values must be version strings.
            if manager=='Npm' and any(not isinstance(v,str) for v in deps.values()):continue
            return {'version':package.get('version',''),'description':desc or None,'license':license,
                    'dependencies':f'{len(deps)} ({manager})' if deps else ''}
        except (OSError,UnicodeError,ValueError,KeyError,TypeError,AttributeError):continue
    return None


def detect_license(root):
    try:entries=list(os.scandir(root))
    except OSError:return ''
    found=[]
    for entry in entries:
        if not entry.is_file() or not entry.name.startswith(('LICENSE','LICENCE','COPYING','UNLICENSE')):continue
        try:text=open(entry.path,encoding='utf-8').read()
        except (OSError,UnicodeError):continue
        s=' '.join(text.lower().split())
        license=''
        if 'permission is hereby granted, free of charge' in s and 'software' in s and ('without restriction' in s or 'without limitation' in s):license='MIT'
        elif 'apache license' in s and ('version 2.0' in s or 'version 2' in s) and len(s)>300:license='Apache-2.0'
        elif ('gnu affero general public license' in s) and len(s)>300:license='AGPL-3.0'
        elif ('gnu lesser general public license' in s) and len(s)>300:license='LGPL-3.0' if 'version 3' in s[:300] else 'LGPL-2.1'
        elif ('gnu general public license' in s) and len(s)>300:
            license='GPL-3.0' if 'version 3' in s[:400] else ('GPL-2.0' if 'version 2' in s[:400] else 'GPL-1.0')
        elif 'redistribution and use in source and binary forms' in s:
            license='BSD-3-Clause' if ('neither the name' in s or 'names of its contributors' in s) else 'BSD-2-Clause'
        elif 'permission to use, copy, modify, and/or distribute this software for any purpose with or without fee' in s:license='ISC'
        elif 'this is free and unencumbered software released into the public domain' in s:license='Unlicense'
        elif 'mozilla public license' in s and ('version 2.0' in s or ', v. 2.0' in s):license='MPL-2.0'
        elif 'do what the fuck you want to public license' in s:license='WTFPL'
        elif 'zlib' in s and 'altered source versions' in s:license='Zlib'
        elif 'creative commons' in s and ('cc0' in s or 'universal' in s):license='CC0-1.0'
        if license and license not in found:found.append(license)
    return ', '.join(found)


