"""Structured and terminal presentation of repository information."""
import json
import math
import os
import re
import unicodedata
from .chips import CHIPS
from .language_data import LANGUAGES
from .ui import UI

ESC='\x1b['
RESET=ESC+'0m'
DEFAULT=ESC+'39m'
ANSI_RE=re.compile(r'\x1b\[[0-9;?]*[A-Za-z]')


def width(text):
    text=ANSI_RE.sub('',text)
    return sum(0 if unicodedata.combining(c) else 2 if unicodedata.east_asian_width(c) in ('W','F') else 1 for c in text)


def color_code(n):
    return str(30+n) if n<8 else str(90+n-8)


def paint(s,color,bold=False):
    return ESC+color+(';1' if bold else '')+'m'+s+RESET


def format_number(n,opts):
    sep={'plain':'','comma':',','space':' ','underscore':'_'}[opts['number-separator']]
    if not sep:return str(n)
    return format(n,',').replace(',',sep)


def yaml_scalar(x):
    if x is None:return 'null'
    if isinstance(x,bool):return 'true' if x else 'false'
    if isinstance(x,(int,float)):return json.dumps(x)
    s=str(x)
    if not s:return "''"
    if any(ord(c)<32 for c in s) or '\t' in s:return json.dumps(s,ensure_ascii=False)
    quote=(s!=s.strip() or s[0] in "!&*{}[],#|>@`\"'%" or s in ('-','?',':') or s.startswith(('- ','? ',': ')) or ': ' in s or s.endswith(':') or ' #' in s)
    if s.lower() in ('null','true','false','~','.nan','.inf','-.inf','+.inf'):quote=True
    if re.fullmatch(r'[-+]?(?:\d[\d_]*(?:\.\d*)?(?:e[-+]?\d+)?|\.\d+|0x[\da-f]+|0o[0-7]+)',s,re.I):quote=True
    return "'"+s.replace("'","''")+"'" if quote else s


