            lines.append(keyprefix+mode)
            for line in value.rstrip('\n').split('\n'):lines.append(' '*(indent+2)+line)
            if mode=='|+':lines.extend(['']*(len(value)-len(value.rstrip('\n'))-1))
        else:lines.append(keyprefix+yaml_scalar(value))
