def check_image(opts):
    if 'image' not in opts:return
    path=opts['image']
    try:
        with open(path,'rb') as f:header=f.read(64)
    except OSError as e:
        cause=f'{e.strerror} (os error {e.errno})'
        raise Exit(1,f"Error: Could not load the image file at '{path}'\n\nCaused by:\n    {cause}\n")
    ext=os.path.splitext(path)[1][1:].lower()
    known={'png','jpg','jpeg','gif','webp','bmp','ico','tif','tiff','pnm','ppm','pgm','pbm','tga','dds','hdr','ff','exr','qoi','avif'}
    if ext not in known:
        msg=f'The file extension `.{json.dumps(ext)}` was not recognized as an image format' if ext else 'The image format could not be determined'
        raise Exit(1,f"Error: Could not load the image file at '{path}'\n\nCaused by:\n    {msg}\n")
    if ext=='png' and not header.startswith(b'\x89PNG\r\n\x1a\n'):
        raise Exit(1,f"Error: Could not load the image file at '{path}'\n\nCaused by:\n    Format error decoding Png: Invalid PNG signature.\n")
    if not header:
        raise Exit(1,f"Error: Could not load the image file at '{path}'\n\nCaused by:\n    unexpected end of file\n")
    error='Failed to render image' if 'image-protocol' in opts else 'Failed to recieve terminal attibutes'
    raise Exit(1,f'Error: {error}\n\nCaused by:\n    Inappropriate ioctl for device (os error 25)\n')


def main():
    try:
        opts=parse(sys.argv[1:])
        if opts.get('generate'):
            sys.stdout.write(UI['completions'][opts['generate']]);return
        if opts.get('languages'):
            sys.stdout.write(UI['languages']);return
        if opts.get('package-managers'):
            sys.stdout.write('Npm\nCargo\n');return
        repo=Repository(opts['input'])
        check_image(opts)
        data,languages=repo.information(opts)
        if opts.get('output')=='json':sys.stdout.write(json.dumps(data,ensure_ascii=False,indent=2))
        elif opts.get('output')=='yaml':sys.stdout.write(yaml_output(data))
        else:
            if 'ascii-input' in opts and not opts['ascii-input'] and not opts.get('no-art'):
                ident=str(uuid.uuid4())
                raise Exit(101,'Well, this is embarrassing.\n\nonefetch had a problem and crashed. To help us diagnose the problem you can send us a crash report.\n\nWe have generated a report file at "/tmp/report-'+ident+'.toml". Submit an issue or email with the subject of "onefetch Crash Report" and include the report as an attachment.\n\n- Homepage: https://onefetch.dev\n- Authors: o2sh <ossama-hjaji@live.fr>\n\nWe take privacy seriously, and do not perform any automated error collection. In order to improve the software, we rely on people to submit reports.\n\nThank you kindly!\n')
            sys.stdout.write(Terminal(opts,languages).render(data))
    except Exit as e:
        (sys.stderr if e.stderr else sys.stdout).write(e.text)
        sys.exit(e.code)
    except BrokenPipeError:
        try:sys.stdout.close()
        except OSError:pass
        sys.exit(0)

