"""Glob matching used by the CLI's file and churn exclusions."""
import re
from functools import lru_cache
from .cli import Exit

@lru_cache(maxsize=256)
def compile_glob(pattern):
    def error(message):
        raise Exit(1,f"Error: error parsing glob '{pattern}': {message}\n")
    def translate(s):
        out='';i=0
        while i<len(s):
            c=s[i];i+=1
            if c=='\\':
                if i==len(s):error("dangling '\\'")
                out+=re.escape(s[i]);i+=1
            elif c=='*':
                if s[i:i+2]=='*/':out+='(?:.*/)?';i+=2
                else:out+='.*'
            elif c=='?':out+='.'
            elif c=='[':
                end=s.find(']',i)
                if end<0:error("unclosed character class; missing ']'")
                chars=s[i:end]
                if chars.startswith('!'):chars='^'+chars[1:]
                for a,b in re.findall(r'(.)-(.)',chars):
                    if ord(a)>ord(b):error(f"invalid range; '{a}' > '{b}'")
                out+='['+chars+']';i=end+1
            elif c=='{':
                depth=1;start=i;pieces=[]
                while i<len(s) and depth:
                    if s[i]=='{':depth+=1
                    elif s[i]=='}':
                        depth-=1
                        if depth==0:pieces.append(s[start:i]);i+=1;break
                    elif s[i]==',' and depth==1:pieces.append(s[start:i]);start=i+1
                    i+=1
                if depth:error("unclosed alternate group; missing '}' (maybe escape '{' with '[{]'?)")
                out+='(?:'+'|'.join(translate(p) for p in pieces)+')'
            else:out+=re.escape(c)
        return out
    try:return re.compile('^'+translate(pattern)+'$',re.DOTALL)
    except re.error:return re.compile(r'(?!)')


def cli_excluded(path,patterns,components=False):
    candidates=path.split('/') if components else [path]
    for pattern in patterns:
        glob=compile_glob(pattern.rstrip('/') if components else pattern)
        if any(glob.fullmatch(s) for s in candidates):return True
    return False
